const storage={get(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}},remove(k){try{localStorage.removeItem(k);}catch{}}};
const DEFAULTS={moveSpeed:5.4,sneakSpeed:2.4,guardSpeed:2.35,sight:9.5,alertRate:25,heartRegen:2.8,pulseCost:12,flightSpeed:8.5};
const EMPTY=()=>({x:0,z:0,interact:false,hide:false,candy:false,pulse:false,boost:false});
const PARTS=[{id:'toy',name:'Toy keyboard',short:'Keyboard',icon:'▥',x:-22,z:10,line:'Six sticky keys. A whole universe of possibilities.'},{id:'record',name:'Record player',short:'Record player',icon:'◎',x:22,z:4,line:'It only plays one record. Tonight, that might be enough.'},{id:'antenna',name:'Antenna',short:'Antenna',icon:'⋔',x:-16,z:-12,line:'A bent coat hanger. He holds it like a shooting star.'}];
